//! Code generation for protobus.
//!
//! protobus schemas are ordinary `.proto` files shared by every language. In
//! `build.rs`:
//!
//! ```no_run
//! fn main() -> Result<(), Box<dyn std::error::Error>> {
//!     protobus_build::configure().proto_dir("proto").compile()?;
//!     Ok(())
//! }
//! ```
//!
//! and in the crate:
//!
//! ```ignore
//! pub mod proto {
//!     protobus::include_protos!();
//! }
//! ```
//!
//! Messages are generated by [prost](https://docs.rs/prost). Each proto
//! package becomes a module, and each service in it gets:
//!
//! | | |
//! |---|---|
//! | `<Service>Handler` | the trait a service implements: an async method per rpc |
//! | `<Service>Service` | a `protobus::MessageService` built around a handler |
//! | `<Service>Proxy` | a typed client |
//!
//! The schemas are compiled in pure Rust: no `protoc` is needed.

#![forbid(unsafe_code)]

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

pub use protobus_schema::{CustomType, SchemaError, WireType};

/// The file [`Builder::compile`] writes for `protobus::include_protos!` to include.
pub const INCLUDE_FILE: &str = "protobus_gen.rs";

/// The descriptor set generated code embeds, beside [`INCLUDE_FILE`].
pub const DESCRIPTOR_FILE: &str = "protobus_descriptor.bin";

/// Start configuring a build.
pub fn configure() -> Builder {
    Builder::default()
}

/// Generates Rust code from protobus schemas.
#[derive(Debug, Default)]
pub struct Builder {
    proto_dirs: Vec<PathBuf>,
    custom_types: Vec<CustomType>,
    out_dir: Option<PathBuf>,
    descriptor_out: Option<PathBuf>,
    protobus_path: Option<String>,
    quiet: bool,
}

impl Builder {
    /// A directory of `.proto` files, read recursively. Paths inside it are
    /// the import paths: `proto/billing/invoice.proto` is
    /// `billing/invoice.proto`.
    pub fn proto_dir(mut self, dir: impl AsRef<Path>) -> Self {
        self.proto_dirs.push(dir.as_ref().to_path_buf());
        self
    }

    /// Declare a custom type of your own: a root-level message
    /// `NAME { optional WIRE value = 1; }`, like the built-in `bigint` and
    /// `timestamp`, so schemas use it without an import. Every port that
    /// shares the schema must declare it the same way.
    pub fn custom_type(mut self, name: &str, wire: WireType) -> Self {
        self.custom_types.push(CustomType::new(name, wire));
        self
    }

    /// Where the generated code goes. Default: `OUT_DIR`.
    pub fn out_dir(mut self, dir: impl AsRef<Path>) -> Self {
        self.out_dir = Some(dir.as_ref().to_path_buf());
        self
    }

    /// Also write the compiled descriptor set here, for the ports that load
    /// schemas as descriptor sets.
    pub fn descriptor_out(mut self, path: impl AsRef<Path>) -> Self {
        self.descriptor_out = Some(path.as_ref().to_path_buf());
        self
    }

    /// The path generated code refers to the `protobus` crate by. Default:
    /// `::protobus`.
    pub fn protobus_path(mut self, path: &str) -> Self {
        self.protobus_path = Some(path.to_string());
        self
    }

    /// Do not print `cargo:rerun-if-changed` lines (outside a build script).
    pub fn quiet(mut self) -> Self {
        self.quiet = true;
        self
    }

    /// Generate the code.
    pub fn compile(self) -> Result<(), Box<dyn std::error::Error>> {
        if self.proto_dirs.is_empty() {
            return Err(Box::new(SchemaError("no proto directory given".into())));
        }
        let out_dir = match &self.out_dir {
            Some(dir) => dir.clone(),
            None => PathBuf::from(std::env::var_os("OUT_DIR").ok_or_else(|| {
                SchemaError("OUT_DIR is not set: call out_dir() when generating outside a build script".into())
            })?),
        };
        std::fs::create_dir_all(&out_dir)?;
        if !self.quiet {
            for dir in &self.proto_dirs {
                println!("cargo:rerun-if-changed={}", dir.display());
            }
        }

        let set = protobus_schema::compile_dirs(&self.proto_dirs, &self.custom_types)?;
        // The embedded set carries no comments: the generator reads them, the program has no use for them.
        let mut embedded = set.clone();
        protobus_schema::strip_source_info(&mut embedded);
        let encoded = prost::Message::encode_to_vec(&embedded);
        std::fs::write(out_dir.join(DESCRIPTOR_FILE), &encoded)?;
        if let Some(path) = &self.descriptor_out {
            if let Some(parent) = path.parent().filter(|p| !p.as_os_str().is_empty()) {
                std::fs::create_dir_all(parent)?;
            }
            std::fs::write(path, &encoded)?;
        }

        let protobus = self.protobus_path.clone().unwrap_or_else(|| "::protobus".into());
        let mut config = prost_build::Config::new();
        config
            .out_dir(&out_dir)
            .enable_type_names()
            .include_file(INCLUDE_FILE)
            // The built-in custom types live in the runtime, with their conversions.
            .extern_path(".bigint", format!("{protobus}::types::Bigint"))
            .extern_path(".timestamp", format!("{protobus}::types::Timestamp"))
            .service_generator(Box::new(ServiceGenerator { protobus }));
        // prost's own derive is reached through the runtime, so a program
        // needs no dependency of its own on prost.
        config.prost_path(format!(
            "{}::prost",
            self.protobus_path.as_deref().unwrap_or("::protobus")
        ));
        config.compile_fds(set)?;

        let include = out_dir.join(INCLUDE_FILE);
        let mut generated = std::fs::read_to_string(&include)?;
        write!(
            generated,
            "\n/// The compiled schemas this code was generated from, registered with a\n\
             /// context's factory by every service and proxy here.\n\
             pub const FILE_DESCRIPTOR_SET: &[u8] = include_bytes!(\"{DESCRIPTOR_FILE}\");\n"
        )?;
        std::fs::write(&include, generated)?;
        Ok(())
    }
}

struct ServiceGenerator {
    protobus: String,
}

/// Names a generated proxy defines itself; an rpc of the same name gets a
/// trailing underscore.
const PROXY_RESERVED: [&str; 5] = ["new", "with_name", "raw", "clone", "NAME"];

/// Write a doc comment; returns whether anything was written.
fn doc(buf: &mut String, indent: &str, comments: &prost_build::Comments, fallback: &str) -> bool {
    let mut any = false;
    for line in comments.leading.iter().flat_map(|block| block.lines()) {
        any = true;
        let _ = writeln!(
            buf,
            "{indent}///{}{}",
            if line.starts_with(' ') || line.is_empty() {
                ""
            } else {
                " "
            },
            line
        );
    }
    if !any && !fallback.is_empty() {
        let _ = writeln!(buf, "{indent}/// {fallback}");
        any = true;
    }
    any
}

impl prost_build::ServiceGenerator for ServiceGenerator {
    fn generate(&mut self, service: prost_build::Service, buf: &mut String) {
        let pb = &self.protobus;
        let name = &service.name;
        let full_name = if service.package.is_empty() {
            service.proto_name.clone()
        } else {
            format!("{}.{}", service.package, service.proto_name)
        };
        // The descriptor set is declared where the generated code is included,
        // above every package's module.
        let depth = if service.package.is_empty() {
            0
        } else {
            service.package.split('.').count()
        };
        let descriptor = format!("{}FILE_DESCRIPTOR_SET", "super::".repeat(depth));
        // Client streaming is not part of the protobus protocol.
        let methods: Vec<&prost_build::Method> = service.methods.iter().filter(|m| !m.client_streaming).collect();
        let signature = |m: &prost_build::Method| {
            format!(
                "rpc {}({}) returns ({}{})",
                m.proto_name,
                m.input_proto_type.trim_start_matches('.'),
                if m.server_streaming { "stream " } else { "" },
                m.output_proto_type.trim_start_matches('.')
            )
        };

        // ---- the handler trait ---------------------------------------------------
        doc(
            buf,
            "",
            &service.comments,
            &format!("Implement this to serve `{full_name}`."),
        );
        let _ = writeln!(
            buf,
            "///\n/// Every rpc defaults to answering `PROTOCOL_ERROR`, so implement the ones you\n\
             /// serve. A handler runs in parallel with others: its state must be `Sync`.\n\
             #[allow(clippy::wrong_self_convention)]\n\
             pub trait {name}Handler: Send + Sync + 'static {{"
        );
        for m in &methods {
            let gap = if doc(buf, "    ", &m.comments, "") {
                "    ///\n"
            } else {
                ""
            };
            let _ = writeln!(buf, "{gap}    /// `{}`", signature(m));
            let method = format!("{full_name}.{}", m.proto_name);
            if m.server_streaming {
                let _ = writeln!(
                    buf,
                    "    fn {fname}(&self, request: {input}, call: {pb}::CallContext, out: {pb}::StreamWriter<{output}>) \
                     -> impl ::std::future::Future<Output = {pb}::Result<()>> + Send {{\n        \
                     async move {{ let _ = (request, call, out); Err({pb}::Error::unimplemented({method:?})) }}\n    }}",
                    fname = m.name,
                    input = m.input_type,
                    output = m.output_type
                );
            } else {
                let _ = writeln!(
                    buf,
                    "    fn {fname}(&self, request: {input}, call: {pb}::CallContext) \
                     -> impl ::std::future::Future<Output = {pb}::Result<{output}>> + Send {{\n        \
                     async move {{ let _ = (request, call); Err({pb}::Error::unimplemented({method:?})) }}\n    }}",
                    fname = m.name,
                    input = m.input_type,
                    output = m.output_type
                );
            }
        }
        buf.push_str("}\n\n");

        // ---- the service ---------------------------------------------------------
        let _ = writeln!(
            buf,
            "/// The [`{pb}::MessageService`] that serves `{full_name}` with a [`{name}Handler`].\n\
             /// It dereferences to the service: call `init()` on it to start serving.\n\
             #[derive(Clone)]\n\
             pub struct {name}Service {{\n    service: {pb}::MessageService,\n}}\n\n\
             impl ::std::ops::Deref for {name}Service {{\n    \
             type Target = {pb}::MessageService;\n\n    \
             fn deref(&self) -> &{pb}::MessageService {{\n        &self.service\n    }}\n}}\n\n\
             impl ::std::convert::From<{name}Service> for {pb}::MessageService {{\n    \
             fn from(service: {name}Service) -> Self {{\n        service.service\n    }}\n}}\n\n\
             impl {name}Service {{\n    \
             /// The service's name on the bus.\n    \
             pub const NAME: &'static str = {full_name:?};\n\n    \
             /// A service named [`NAME`](Self::NAME), with default options.\n    \
             pub fn new<H: {name}Handler>(context: &{pb}::Context, handler: H) -> {pb}::Result<Self> {{\n        \
             Self::with_options(context, Self::NAME, handler, ::std::default::Default::default())\n    }}\n\n    \
             /// A service under a name of your choosing (an instance name such as\n    \
             /// `{full_name}.one` serves the same contract), with options.\n    \
             pub fn with_options<H: {name}Handler>(\n        context: &{pb}::Context,\n        service_name: &str,\n        handler: H,\n        \
             options: {pb}::MessageServiceOptions,\n    ) -> {pb}::Result<Self> {{\n        \
             Self::from_arc(context, service_name, ::std::sync::Arc::new(handler), options)\n    }}\n\n    \
             /// As [`with_options`](Self::with_options), for a handler you keep a handle to.\n    \
             pub fn from_arc<H: {name}Handler>(\n        context: &{pb}::Context,\n        service_name: &str,\n        \
             handler: ::std::sync::Arc<H>,\n        options: {pb}::MessageServiceOptions,\n    ) -> {pb}::Result<Self> {{\n        \
             let service = {pb}::MessageService::new(context, service_name, options)?.with_schema({descriptor});"
        );
        for m in &methods {
            let (register, args, call_args) = if m.server_streaming {
                ("register_stream", "request, call, out", "request, call, out")
            } else {
                ("register_unary", "request, call", "request, call")
            };
            let closure_args = if m.server_streaming {
                format!(
                    "request: {}, call, out: {pb}::StreamWriter<{}>",
                    m.input_type, m.output_type
                )
            } else {
                format!("request: {}, call", m.input_type)
            };
            let _ = args;
            let _ = writeln!(
                buf,
                "        {{\n            let handler = handler.clone();\n            \
                 service.{register}({proto:?}, move |{closure_args}| {{\n                \
                 let handler = handler.clone();\n                \
                 async move {{ handler.{fname}({call_args}).await }}\n            }});\n        }}",
                proto = m.proto_name,
                fname = m.name
            );
        }
        if methods.is_empty() {
            buf.push_str("        let _ = handler;\n");
        }
        buf.push_str(
            "        Ok(Self { service })\n    }\n\n    /// The service itself.\n    pub fn into_inner(self) -> ",
        );
        let _ = writeln!(buf, "{pb}::MessageService {{\n        self.service\n    }}\n}}\n");

        // ---- the proxy -----------------------------------------------------------
        let taken: Vec<String> = methods.iter().map(|m| m.name.clone()).collect();
        let _ = writeln!(
            buf,
            "/// Calls `{full_name}`. Cheap to clone, and safe to use from any number of tasks at once.\n\
             #[derive(Clone)]\n\
             pub struct {name}Proxy {{\n    proxy: {pb}::ServiceProxy,\n}}\n\n\
             impl {name}Proxy {{\n    \
             /// The service's name on the bus.\n    \
             pub const NAME: &'static str = {full_name:?};\n\n    \
             /// A proxy for the service named [`NAME`](Self::NAME).\n    \
             pub fn new(context: &{pb}::Context) -> {pb}::Result<Self> {{\n        \
             Self::with_name(context, Self::NAME)\n    }}\n\n    \
             /// A proxy for an instance of the service registered under another name.\n    \
             pub fn with_name(context: &{pb}::Context, service_name: &str) -> {pb}::Result<Self> {{\n        \
             context.factory().register_descriptor_set({descriptor})?;\n        \
             let proxy = {pb}::ServiceProxy::new(context, service_name);\n        \
             proxy.init()?;\n        \
             Ok(Self {{ proxy }})\n    }}\n\n    \
             /// The untyped proxy underneath.\n    \
             pub fn raw(&self) -> &{pb}::ServiceProxy {{\n        &self.proxy\n    }}"
        );
        for m in &methods {
            let mut fname = m.name.clone();
            if PROXY_RESERVED.contains(&fname.as_str()) {
                fname.push('_');
            }
            let mut with = format!("{}_with", m.name.trim_start_matches("r#"));
            if taken.contains(&with) {
                with.push('_');
            }
            buf.push('\n');
            let gap = if doc(buf, "    ", &m.comments, "") {
                "    ///\n"
            } else {
                ""
            };
            let _ = writeln!(buf, "{gap}    /// `{}`", signature(m));
            if m.server_streaming {
                let _ = writeln!(
                    buf,
                    "    pub fn {fname}(&self, request: {input}) -> {pb}::Result<{pb}::Stream<{output}>> {{\n        \
                     self.{with}(request, ::std::default::Default::default())\n    }}\n\n    \
                     /// `{proto}`, with options.\n    \
                     pub fn {with}(&self, request: {input}, options: {pb}::StreamOptions) -> {pb}::Result<{pb}::Stream<{output}>> {{\n        \
                     self.proxy.call_stream_typed({proto:?}, &request, &options)\n    }}",
                    input = m.input_type,
                    output = m.output_type,
                    proto = m.proto_name
                );
            } else {
                let _ = writeln!(
                    buf,
                    "    pub async fn {fname}(&self, request: {input}) -> {pb}::Result<{output}> {{\n        \
                     self.proxy.call_typed({proto:?}, &request, &::std::default::Default::default()).await\n    }}\n\n    \
                     /// `{proto}`, with options.\n    \
                     pub async fn {with}(&self, request: {input}, options: {pb}::CallOptions) -> {pb}::Result<{output}> {{\n        \
                     self.proxy.call_typed({proto:?}, &request, &options).await\n    }}",
                    input = m.input_type,
                    output = m.output_type,
                    proto = m.proto_name
                );
            }
        }
        buf.push_str("}\n");
    }
}
